import csv
from collections import defaultdict

def performance_report(employee_id=None, report_type='summary'):
    '''
    Create a performance_report function that reads performance_reviews.csv from PROJECT KNOWLEDGE. Parameters: employee_id (optional string), report_type (string, default 'summary'). RETURN TYPES AND FIELD SPECIFICATIONS: (1) summary mode - find CSV row where employee_id column matches parameter, return single dict with keys 'employee_id' (string value), 'overall_rating' (float from CSV column - keep as float not string), 'goals_status' (string from CSV column). (2) detailed mode - find matching row, return single dict with ALL CSV column names as keys preserving exact names and original types. (3) department mode - when employee_id is None, group rows by 'department' CSV column, return dict where keys are department names and values are dicts with 'avg_rating' (float - average of overall_rating column) and 'count' (int - number of employees).
    '''
    # Helper to cast values to best type according to column
    def cast_row_types(row):
        # Known float columns
        float_cols = {'technical_score', 'communication_score', 'teamwork_score',
                      'leadership_score', 'overall_rating'}
        int_cols = set()  # No int columns
        return {
            k: (float(v) if k in float_cols else v)
            for k, v in row.items()
        }

    # Open CSV and route logic
    with open('performance_reviews.csv', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

        if report_type == 'summary':
            for row in rows:
                if row['employee_id'] == employee_id:
                    return {
                        'employee_id': row['employee_id'],
                        'overall_rating': float(row['overall_rating']),
                        'goals_status': row['goals_status']
                    }
            return None  # If not found

        elif report_type == 'detailed':
            for row in rows:
                if row['employee_id'] == employee_id:
                    # Cast float cols, keep types
                    detailed_row = row.copy()
                    for k in ['technical_score', 'communication_score', 'teamwork_score', 'leadership_score', 'overall_rating']:
                        if k in detailed_row:
                            detailed_row[k] = float(detailed_row[k])
                    return detailed_row
            return None  # If not found

        elif report_type == 'department':
            dept_group = defaultdict(list)
            for row in rows:
                dept = row['department']
                try:
                    rating = float(row['overall_rating'])
                except Exception:
                    continue  # skip if invalid
                dept_group[dept].append(rating)
            result = {}
            for dept, ratings in dept_group.items():
                avg = round(sum(ratings) / len(ratings), 2) if ratings else 0.0
                result[dept] = {'avg_rating': avg, 'count': len(ratings)}
            return result

        else:
            raise ValueError("Unknown report_type: {}".format(report_type))

